// @name Camera wall
// Up to four live cameras side by side: an RTSP feed (rtsp://user:pass@host/…)
// or anything else ffmpeg reads over http(s), an MJPEG camera, an HLS stream
// or a video file's URL. A tap on one fills the screen with it, another tap
// goes back to the wall. A feed that drops is opened again. Plays on a
// Raspberry Pi (docs/video.md); a camera on the local network needs a frame
// that may reach it (a cloud frame's Local network access).
const FIELDS = [1, 2, 3, 4]

let zoomed = -1

function Label({ name, live, k }) {
  return (
    <div className={`absolute left-[${Math.round(8 * k)}px] top-[${Math.round(8 * k)}px] flex items-center gap-[6px] px-[8px] py-[3px] rounded-[6px] bg-black/55`}>
      <div className={`w-[${Math.round(8 * k)}px] h-[${Math.round(8 * k)}px] rounded-full ${live ? 'bg-red-500' : 'bg-white/40'}`} />
      <span className={`text-[${Math.round(13 * k)}px] text-white`}>{name}</span>
    </div>
  )
}

function Camera({ camera, k, fit, fps, onClick }) {
  const video = frameos.video(`camera${camera.n}`, { src: camera.url, loop: true, fps, fit })
  const live = video.state === 'playing'
  return (
    <div className="relative flex-1 h-full bg-neutral-900 overflow-hidden" onClick={onClick}>
      <img className={`w-full h-full object-${fit}`} src={video} />
      {video.state === 'error' ? (
        <div className="absolute left-0 top-0 w-full h-full flex items-center justify-center px-[16px]">
          <span className={`text-[${Math.round(13 * k)}px] text-red-200 text-center`}>{video.error}</span>
        </div>
      ) : video.state === 'loading' ? (
        <div className="absolute left-0 top-0 w-full h-full flex items-center justify-center">
          <span className={`text-[${Math.round(13 * k)}px] text-white/60`}>Connecting…</span>
        </div>
      ) : null}
      <Label name={camera.name} live={live} k={k} />
    </div>
  )
}

export function get(app, context) {
  const width = context?.imageWidth ?? app.frame.width
  const height = context?.imageHeight ?? app.frame.height
  const k = Math.max(0.6, Math.min(1.4, Math.min(width / 800, height / 480)))
  const cameras = FIELDS.map((n) => ({
    n,
    url: String(app.state[`camera${n}`] ?? '').trim(),
    name: String(app.state[`name${n}`] ?? '').trim() || `Camera ${n}`,
  })).filter((camera) => camera.url)
  if (!cameras.length) {
    // Read on any panel: 14 px at the least, in a column 70 % of the width
    // and centred (inside the circle on a round one), white on e-paper.
    return (
      <div className="w-full h-full flex flex-col items-center justify-center gap-[8px] bg-black text-white">
        <span className={`text-[${Math.max(18, Math.round(22 * k))}px] font-bold`}>Camera wall</span>
        <span className={`w-[${Math.round(width * 0.7)}px] text-[${Math.max(14, Math.round(15 * k))}px] ${app.frame.paper ? 'text-white' : 'text-white/70'} text-center`}>
          Give up to four camera addresses in the scene's settings: rtsp://, http:// or https://.
        </span>
      </div>
    )
  }
  const fit = app.state.fit === 'contain' ? 'contain' : 'cover'
  const fps = Number(app.state.fps) || 15
  if (zoomed >= cameras.length) zoomed = -1
  if (zoomed >= 0) {
    const camera = cameras[zoomed]
    return (
      <div className="flex w-full h-full bg-black">
        <Camera camera={camera} k={k} fit={fit} fps={fps} onClick={() => { zoomed = -1 }} />
      </div>
    )
  }
  const tile = (camera, i) => <Camera camera={camera} k={k} fit={fit} fps={fps} onClick={() => { zoomed = i }} />
  const gap = Math.max(2, Math.round(4 * k))
  // One, two side by side (above each other on a tall screen), or a grid of
  // four (three leave a dark corner).
  if (cameras.length === 1) {
    return <div className="flex w-full h-full bg-black">{tile(cameras[0], 0)}</div>
  }
  if (cameras.length === 2) {
    return (
      <div className={`flex ${height > width ? 'flex-col' : ''} w-full h-full gap-[${gap}px] bg-black`}>
        {tile(cameras[0], 0)}
        {tile(cameras[1], 1)}
      </div>
    )
  }
  return (
    <div className={`flex flex-col w-full h-full gap-[${gap}px] bg-black`}>
      <div className={`flex flex-1 gap-[${gap}px]`}>
        {tile(cameras[0], 0)}
        {tile(cameras[1], 1)}
      </div>
      <div className={`flex flex-1 gap-[${gap}px]`}>
        {tile(cameras[2], 2)}
        {cameras[3] ? tile(cameras[3], 3) : <div className="flex-1 h-full bg-neutral-950" />}
      </div>
    </div>
  )
}
